# Review 136 VPS deployment. Run once in an elevated PowerShell on the VPS.
#   Check only, changes nothing:  powershell -ExecutionPolicy Bypass -File .\Deploy136.ps1 -Check
#   Deploy:                       powershell -ExecutionPolicy Bypass -File .\Deploy136.ps1
# Order is fixed: online backup (which runs the whole-file integrity checks), stop, files, start. There
# is no schema version change. On first start the backend adds perf136_ indexes and one bookkeeping table, which the
# schema validators ignore. Any failed check stops the service, removes those objects, restores the
# previous files and starts the previous backend. Caddy is unchanged. levels.json is not part of this.
# No credentials are embedded or printed.
param([switch]$Check)
$ErrorActionPreference='Stop'
Set-StrictMode -Version Latest
$files=@(
    @{name='api.py';old='f7c32772e5b735244ec178ac05ccc514b83e2857042fbd01f763c14c0971ff79';new='d4f29fc3d45f19d60f77e7d81dfaeb2afd6f5466af402966b47bb3e329f793c8';data=''}
    @{name='friends.py';old='519c538db0ef7b21e2d5d6e22fa3e546e61ccc2e54f69cc7bd4debac90cf0215';new='d48fae5c08ae231ebf2d9e656bf9996e934bc66808d3f0bf634d57c3fcb64b12';data=''}
    @{name='identity.py';old='6eecbc26cc378ce32c2ee3923073716e787a220d10e6a7ac65ce9c98cbd14e65';new='82a7c12988ac59db24630d040375e7fac6828b93c4f1d20435e9be7c02b49ac7';data=''}
    @{name='messaging.py';old='f26c7441eac8fa07b9e2b28667009f3886a3a4ebdd5ea4ba4ee81da700335f80';new='0537e45581d11d6ee76c23d48ea78bcf7d06f731414c1cd5018fb389166670d6';data=''}
    @{name='newads.py';old='68fdc0e366e5c0a48094e7f72222ca60550b1476c71e8f579ec0e9552843ee9d';new='9247f2ef256bac34b53d80e8da67d5df666df34170f4ee2b6ef768e38c0f17d4';data=''}
    @{name='operations.py';old='415c8cfd8cc2bc7e06afcb6dd03e6386c7bdd29acaf90de5ea73cbd6a4224ed1';new='39900c83434caeeb0f8dfef925da042901641c1f92fcfc23c857051df3f11581';data=''}
    @{name='production_runtime122.py';old='7adfba459847ba64c65f17ec3fa6353d07cf060bbfa6d33999df5938259fa3c0';new='b790d8899f90cb834f9a3502e8581aa2a37f8ca78642eb14bd77d74f894fea92';data=''}
    @{name='readiness.py';old='7ff208fc9692e4e715a97e941eae89e648e065f1e8fdd524020ceb90570e42df';new='6b11e74623d78207940fdc030d16b0598d6def2aadd12a1fbf45fdb8b10c3bd4';data=''}
    @{name='records.py';old='92980d701ab2c2540618d9b5fc64847dcf797a87eb25c7871d60091635bf7db0';new='70c631a5c0979baabccefa927bfdd84a589a008df97fa6ab682e092d3249fc6b';data=''}
    @{name='regions.py';old='e1e523ac77602ae6e3a15bc1d6d577417e9bb757aaa2e5f47895bdbd70428694';new='b3d4af2d0bff92f5040831938232a0a2ae1ae469b3db7c301e415b0564a97f2f';data=''}
    @{name='replay_contract.py';old='951ee27954f7540295e86975de4eba0499504786dbecb331d66eea9912b9d805';new='b987de26a19c4fc35283134667ee55742c6a637dbb327b7eda52e3daec661f0c';data=''}
    @{name='replay_service.py';old='2c87bfc79dcc382885bd0465adea2cbc105459a531af43cf644fdf2324bd881d';new='8efb928d21aa6cf94b4ab5d0e727d1620c71d58e3c3af8e16a38db57718a4a20';data=''}
    @{name='sdk_schema125.py';old='4fa42d11e084b5e2dd5ba638d3511c0b91b51ec70e88b9c3a417759617f2326e';new='7ca5081383201ae86e31af40105b25feddbad15a4f735dd315df58c609f32343';data=''}
    @{name='service.py';old='4a9b68af2125d68e9ec4746ca928ce6a042849d2ee11d374e73e99a9bd8373f1';new='9d5ed1a99f966e2d6ace887343e556bf52227be4f7bda4be867dbfab07af6c32';data=''}
    @{name='staging105.py';old='2f3457d397949b4a1e79f270abc54b08e9e66bf384793e20ece727746f6a29bf';new='28da1c042a6c095f9b30f363cd68c2ed0fa2a9926362a09190210f5be390b3b7';data=''}
    @{name='staging_sdk126.py';old='f952fd2ef92b4efecdb6d787cf7ee73c468f9ed1e2ee589784e10be906bf7db0';new='609786dd0034ffc6399dae8e330aba716f54956d661bb377bdcc210a8f7fb6ce';data=''}
    @{name='storage.py';old='01347b76bf11ca4d5399bb2018e1eedf77650973d63129a5440bc3aa2e9a37b3';new='e5e3dd611f92861e2c0baddf284914e779e681df2f8a723ac5953c148b28ea66';data=''}
    @{name='team_mail111.py';old='f1afb59c7a7e6a5c03b725ce9d90862e50ad328db369407dc26c266ffa834460';new='624b085ca44f97cbf3fb9046e9b46475c0b61d1847ede91f471aa0ed734eeead';data=''}
    @{name='wallet.py';old='bb0a377a37a7ad3fdf16c29ec359754feb5c08c1f92789f3b3fde5513ee8a235';new='da99045cb65764e9fd890de564f200d1b46ec5e844e8f93bb9f85a7340cf208b';data=''}
    @{name='runtime136.py';old='';new='7a7a914ba464c2cb4e8bb1e1f4a5923cc608c2a746124ab9f43d6276f3f067ed';data=''}
)
$Backend='C:\Apps\HeartOfTheRain\Monetization126\Backend'
$Source=Join-Path $Backend 'hotr_backend'
$Python='C:\Apps\HeartOfTheRain\Backend\.venv-service\Scripts\python.exe'
$Services='C:\ProgramData\HeartOfTheRain\services'
$Manifest=Join-Path $Services 'staging-manifest.json'
$Stamp=(Get-Date).ToUniversalTime().ToString('yyyyMMddHHmmss')
$Backup='C:\ProgramData\HeartOfTheRain\Review136Backup\'+$Stamp
$Public='https://api.novamind-it.ru'
function Sha([string]$Path){(Get-FileHash -LiteralPath $Path -Algorithm SHA256).Hash.ToLowerInvariant()}
function Up([string]$Url){try{(Invoke-WebRequest -Uri $Url -UseBasicParsing -TimeoutSec 8).StatusCode -eq 200}catch{$false}}
function WaitUp([string]$Url,[int]$Seconds){$end=(Get-Date).AddSeconds($Seconds);while((Get-Date) -lt $end){if(Up $Url){return $true};Start-Sleep -Seconds 2};return $false}
# Windows PowerShell 5.1 turns any stderr line from a native command into a fatal error under Stop.
# Only the exit code decides a step.
function RunPython([string[]]$Arguments){
    $previous=$ErrorActionPreference
    $ErrorActionPreference='Continue'
    Push-Location $Backend
    try{$lines=& $Python @Arguments 2>$null;$code=$LASTEXITCODE}finally{Pop-Location;$ErrorActionPreference=$previous}
    if($lines){$lines|ForEach-Object{Write-Output $_}}
    if($code -ne 0){throw ('Python step failed with exit code '+$code)}
}
$principal=New-Object Security.Principal.WindowsPrincipal([Security.Principal.WindowsIdentity]::GetCurrent())
if(-not $principal.IsInRole([Security.Principal.WindowsBuiltInRole]::Administrator)){throw 'Run this in an elevated PowerShell.'}
foreach($path in @($Source,$Python,$Manifest)){if(-not (Test-Path -LiteralPath $path)){throw 'Missing: '+$path}}
foreach($service in 'HOTRStaging','HOTRCaddy'){if((Get-Service $service).Status -ne 'Running'){throw $service+' is not running'}}
if(-not (Up 'http://127.0.0.1:8751/readyz')){throw 'The API is not ready before deployment.'}
$pending=@()
foreach($file in $files){
    $target=Join-Path $Source $file.name
    $current=if(Test-Path -LiteralPath $target){Sha $target}else{''}
    if($current -eq $file.new){continue}
    if($current -ne $file.old){throw 'Unexpected live version of '+$file.name+': '+$current}
    $pending+=$file
}
Write-Output ("Preflight OK. Backend files to change: {0} of {1}." -f $pending.Count,$files.Count)
if($Check){Write-Output 'Check only: nothing was changed.';return}
if($pending.Count -eq 0){Write-Output 'Nothing to do.';return}

New-Item -ItemType Directory -Force -Path $Backup | Out-Null
foreach($file in $files){
    $target=Join-Path $Source $file.name
    if(Test-Path -LiteralPath $target){Copy-Item -LiteralPath $target -Destination (Join-Path $Backup $file.name)}
}
foreach($file in $pending){
    $temporary=Join-Path $Backup ($file.name+'.new')
    [IO.File]::WriteAllBytes($temporary,[Convert]::FromBase64String($file.data))
    if((Sha $temporary) -ne $file.new){throw 'Embedded file failed its hash check: '+$file.name}
}
try{RunPython @('-B','-m','hotr_backend.staging_sdk_ops126','backup','--manifest',$Manifest,'--name',('before-review136-'+$Stamp))}
catch{throw 'Online database backup failed; nothing was changed.'}
$DropObjects=@'
import json,sqlite3,sys
from pathlib import Path
manifest=json.loads(Path(sys.argv[1]).read_text('utf-8-sig'))
db=sqlite3.connect(str(Path(manifest['dataDirectory'])/'authority.sqlite3'),timeout=30,isolation_level=None)
db.execute('BEGIN IMMEDIATE')
rows=db.execute("SELECT type,name FROM sqlite_master WHERE substr(name,1,8)='perf136_' ORDER BY type").fetchall()
for kind,name in rows:
    db.execute('DROP '+kind.upper()+' "'+name+'"')
db.commit()
db.close()
print('removed',len(rows))
'@
$restore={
    Stop-Service HOTRStaging -ErrorAction SilentlyContinue
    # A file, not -c: Windows PowerShell 5.1 does not escape double quotes for native arguments.
    $dropFile=Join-Path $Backup 'drop_perf136.py'
    [IO.File]::WriteAllText($dropFile,$DropObjects)
    try{RunPython @('-B',$dropFile,$Manifest)}catch{Write-Output 'WARNING: could not remove the perf136_ objects; the previous backend will refuse this database until they are removed.'}
    foreach($file in $files){
        $saved=Join-Path $Backup $file.name
        $target=Join-Path $Source $file.name
        if(Test-Path -LiteralPath $saved){Copy-Item -LiteralPath $saved -Destination $target -Force}
        elseif(Test-Path -LiteralPath $target){Remove-Item -LiteralPath $target -Force}
    }
    Start-Service HOTRStaging
    if(WaitUp 'http://127.0.0.1:8751/readyz' 180){Write-Output 'Previous backend restored and healthy.'}else{Write-Output 'WARNING: previous backend restored but not ready. Check the HOTRStaging logs.'}
}
Stop-Service HOTRStaging
try{
    foreach($file in $pending){Copy-Item -LiteralPath (Join-Path $Backup ($file.name+'.new')) -Destination (Join-Path $Source $file.name) -Force}
    Start-Service HOTRStaging
}catch{
    & $restore
    throw 'The new backend did not pass its checks; the previous files were restored.'
}
if(-not (WaitUp 'http://127.0.0.1:8751/readyz' 300) -or -not (WaitUp ($Public+'/readyz') 30)){
    & $restore
    throw 'The new backend did not become ready; the previous files were restored.'
}
Write-Output ('Done. Backup: '+$Backup)
Get-Service HOTRStaging,HOTRCaddy | Format-Table Name,Status
foreach($route in '/healthz','/readyz'){Write-Output ($route+': '+(Invoke-WebRequest -Uri ($Public+$route) -UseBasicParsing -TimeoutSec 15).Content)}
